class Solution {
  public int maxRotateFunction(int[] nums) {
    int n = nums.length;
    long sum = 0, f = 0;
    for (int i = 0; i < n; i++) {
      sum += nums[i];
      f += (long) i * nums[i];
    }
    long best = f;
    // F(k) = F(k-1) + sum - n * (element that moves to the front)
    for (int k = 1; k < n; k++) {
      f += sum - (long) n * nums[n - k];
      best = Math.max(best, f);
    }
    return (int) best;
  }
}
